function loadFavorites() { try { const value=JSON.parse(localStorage.getItem("tiddl-player-favorites")||"[]"); return Array.isArray(value)?value.filter(track=>track&&track.id).map(entry=>({...entry,kind:entry.kind||"track"})):[]; } catch { return []; } }
