$("#play").addEventListener("click",()=>{if(state.current<0)return playIndex(0);audio.paused?safePlay():audio.pause();});
$("#previous").addEventListener("click",()=>audio.currentTime>4?audio.currentTime=0:playIndex(state.current-1)); $("#next").addEventListener("click",nextTrack);
$("#shuffle").addEventListener("click",()=>{state.shuffle=!state.shuffle;$("#shuffle").classList.toggle("active",state.shuffle);saveQueueSession();});
$("#repeat").addEventListener("click",()=>{state.repeat=(state.repeat+1)%3;renderRepeatIcon();saveQueueSession();});
function renderRepeatIcon() { const button=$("#repeat"); button.classList.toggle("active",state.repeat>0); button.classList.toggle("single",state.repeat===2); if(state.repeat===2){ button.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 2l4 4-4 4"/><path d="M3 11v-1a4 4 0 0 1 4-4h14"/><path d="M21 13v1a4 4 0 0 1-4 4h-0.5"/><path d="M9.5 18H3"/><path d="M7 22l-4-4 4-4"/><text x="13" y="18" text-anchor="middle" dominant-baseline="central" font-size="11" font-weight="700" fill="currentColor" stroke="none" font-family="inherit">1</text></svg>`; } else { button.innerHTML=`<i data-lucide="repeat"></i>`; } icon(); }
$("#qualityControl").addEventListener("click",event=>{if(state.defaultHighest){if(event.target.closest("#qualityButton")||event.target.closest("[data-quality-choice]"))showToast(t("defaultHighestToast"));return;}const choice=event.target.closest("[data-quality-choice]");if(choice){state.quality=choice.dataset.qualityChoice;state.actualQuality=null;renderQualityControl();if(state.current>=0)playIndex(state.current);return;}if(event.target.closest("#qualityButton")){const menu=$("#qualityMenu");menu.hidden=!menu.hidden;}});
$("#playerSettingsButton").addEventListener("click",()=>$("#playerSettingsDialog").showModal());
$("[data-close-settings]").addEventListener("click",()=>$("#playerSettingsDialog").close());
function updatePlayerSettings(){state.defaultHighest=$("#playerDefaultHighest").checked;state.defaultAtmos=$("#playerDefaultAtmos").checked;localStorage.setItem("tiddl-player-default-highest",state.defaultHighest);localStorage.setItem("tiddl-player-default-atmos",state.defaultAtmos);if(state.current>=0){audio.pause();playIndex(state.current);}else renderQualityControl();}
$("#playerDefaultHighest").addEventListener("change",updatePlayerSettings);$("#playerDefaultAtmos").addEventListener("change",updatePlayerSettings);
$("#volume").addEventListener("input",event=>{audio.volume=Number(event.target.value);audio.muted=false;paintRange(event.target);}); $("#mute").addEventListener("click",()=>{audio.muted=!audio.muted;$("#mute").innerHTML=`<i data-lucide="${audio.muted?"volume-x":"volume-2"}"></i>`;icon();});
$("#seek").addEventListener("input",event=>{if(Number.isFinite(audio.duration))audio.currentTime=audio.duration*Number(event.target.value)/1000;paintRange(event.target);});
audio.addEventListener("timeupdate",()=>{state.streamRetries=0;$("#elapsed").textContent=formatTime(audio.currentTime);$("#duration").textContent=formatTime(audio.duration);if(Number.isFinite(audio.duration))$("#seek").value=audio.currentTime/audio.duration*1000;paintRange($("#seek"));highlightLyrics();}); audio.addEventListener("play",updatePlayButton);audio.addEventListener("pause",updatePlayButton);audio.addEventListener("ended",nextTrack);function streamFailed() { if((state.streamRetries||0)>=2){state.streamRetries=0;showError(t("streamFailed"));return;} state.streamRetries=(state.streamRetries||0)+1; showError(t("loading")); const track=state.queue[state.current]; if(!track)return; audio.pause(); playIndex(state.current); }
audio.addEventListener("error",()=>{if(state.current>=0)streamFailed();else showError("This stream format is not supported by this browser.");});
$("#languageSelect").addEventListener("change",event=>{state.lang=event.target.value;localStorage.setItem("tiddl-language",state.lang);applyLocale();}); $("#themeButton").addEventListener("click",()=>{state.theme=state.theme==="dark"?"light":"dark";localStorage.setItem("tiddl-theme",state.theme);applyTheme();});
document.addEventListener("click",event=>{if(!event.target.closest("#artistSearch")&&!event.target.closest("#artistSearchResults")){const p0=$("#artistSearchResults"); if(p0)p0.hidden=true;}if(!event.target.closest(".player-search-wrap")&&!event.target.closest("#playerSearchResults"))$("#playerSearchResults").hidden=true;if(!event.target.closest("#qualityControl")&&$("#qualityMenu"))$("#qualityMenu").hidden=true;});
document.addEventListener("keydown",event=>{if(document.body.dataset.route!=="player")return;if(event.target.matches("input,select"))return;if(event.code==="Space"){event.preventDefault();$("#play").click();}if(event.code==="ArrowRight")audio.currentTime+=5;if(event.code==="ArrowLeft")audio.currentTime-=5;});
